import { REFERENCES } from './references.js?v=5.4.0-r4';
import { categories, evidenceLabels, methodLabels, l, t, formatNumber, formatUnit } from './i18n.js?v=5.4.0-r4';
import { getRecommendations } from './recommendations.js?v=5.4.0-r4';
import { profileKeys } from './validators.js?v=5.4.0-r4';
import { icon, logo } from './icons.js?v=5.4.0-r4';
import { DOMAIN_CONTENT, WHEN_USEFUL, confidenceFor, fieldHelp, relatedFor, visualizationType } from './content.js?v=5.4.0-r4';
