export const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const active=(r,p)=>r.page===p?'active':'';
const bi=(ru,en,lang)=>lang==='ru'?ru:en;
const count=id=>CALCULATORS.filter(c=>c.category===id).length;
const badge=(calc,lang)=>`<span class="badge method">${esc(l(methodLabels[calc.methodType],lang))}</span><span class="badge evidence-${calc.evidenceStrength}">${esc(l(evidenceLabels[calc.evidenceStrength],lang))}</span>`;
const sectionHead=(eyebrow,title,text='')=>`<header class="section-head"><div>${eyebrow?`<span class="eyebrow">${eyebrow}</span>`:''}<h2>${title}</h2></div>${text?`<p>${text}</p>`:''}</header>`;

export function shell(content,state,r){
 const lang=state.lang,nav=[['home','home','overview'],['calculators','calculators','calculators'],['insights','insights','insights'],['profile','profile','profile'],['evidence','evidence','evidence'],['about','about','about']];
 return `<div class="shell" data-route="${esc(r.page)}"><aside class="sidebar"><a class="brand" href="#home" aria-label="MARKOVLAB">${logo(false,bi("ИЗМЕРИМЫЙ ПРОГРЕСС","MEASURABLE PROGRESS",lang))}</a><nav class="nav" aria-label="${bi('Основная навигация','Primary navigation',lang)}">${nav.map(([p,i,k])=>`<a class="${active(r,p)}" href="#${p}" ${r.page===p?'aria-current="page"':''}>${icon(i)}<span>${t(k,lang)}</span></a>`).join('')}</nav><div class="sidebar-foot"><div class="privacy-mini">${icon('lock')}<div><strong>${t('privacyTitle',lang)}</strong><span>${bi('Без отправки данных','No data upload',lang)}</span></div></div><small>${t('version',lang)}</small></div></aside>
 <div class="content-shell"><header class="topbar"><a class="brand-mobile" href="#home" aria-label="MARKOVLAB">${logo(true)}</a><div class="connection" id="connection" hidden>${t('offline',lang)}</div><div class="top-actions"><button class="search-trigger btn" data-action="palette" aria-label="${t('search',lang)}">${icon('search')}<span>${t('search',lang)}</span><kbd>⌘K</kbd></button><div class="locale-switcher" role="group" aria-label="${t('language',lang)}"><button data-lang="ru" aria-pressed="${lang==='ru'}">RU</button><span aria-hidden="true">/</span><button data-lang="en" aria-pressed="${lang==='en'}">EN</button></div><div class="settings-menu"><button class="icon-btn" data-action="settings-menu" aria-expanded="false" aria-controls="settings-popover" aria-label="${t('theme',lang)}">${icon('theme')}</button><div class="data-popover settings-popover" id="settings-popover"><div class="popover-copy"><strong>${t('theme',lang)}</strong><span>${bi('Выбор применяется сразу и сохраняется локально.','Applied immediately and saved locally.',lang)}</span></div>${[['system','system'],['light','light'],['dark','dark'],['midnight','midnight']].map(([value,key])=>`<button data-theme="${value}" aria-pressed="${state.theme===value}">${state.theme===value?icon('check'):icon('theme')} ${t(key,lang)}</button>`).join('')}</div></div><div class="data-menu"><button class="icon-btn" data-action="data-menu" aria-expanded="false" aria-controls="data-popover" aria-label="${t('data',lang)}">${icon('data')}</button><div class="data-popover" id="data-popover"><div class="popover-copy"><strong>${t('data',lang)}</strong><span>${t('privacyNote',lang)}</span></div><button data-action="export">${icon('data')} ${t('export',lang)}</button><button data-action="import">${icon('calculators')} ${t('import',lang)}</button><button data-action="print">${icon('print')} ${t('print',lang)}</button><button class="danger" data-action="clear-data">${icon('close')} ${t('clear',lang)}</button></div></div></div></header><main class="main" id="main" tabindex="-1">${content}</main></div>
 <nav class="mobile-nav" aria-label="${bi('Мобильная навигация','Mobile navigation',lang)}">${nav.slice(0,5).map(([p,i,k])=>`<a class="${active(r,p)}" href="#${p}" ${r.page===p?'aria-current="page"':''}>${icon(i)}<span>${t(k,lang)}</span></a>`).join('')}</nav></div>`;
}

export function toolCard(calc,state,reason=''){const lang=state.lang,fav=state.favorites.includes(calc.id);return `<article class="tool-card"><a class="card-link" href="#calc/${calc.id}" aria-label="${esc(l(calc.title,lang))}"></a><button class="fav-btn ${fav?'active':''}" data-favorite="${calc.id}" aria-label="${t('favorite',lang)}" aria-pressed="${fav}">${icon('star')}</button><div class="tool-top"><span class="domain-icon">${icon(calc.category)}</span><span class="eyebrow">${esc(l(categories[calc.category],lang))}</span></div><h3>${esc(l(calc.title,lang))}</h3><p>${esc(reason||l(calc.description,lang))}</p><div class="card-meta">${badge(calc,lang)}</div></article>`}

const principles=(lang)=>[
 [icon('profile'),bi('Без аккаунта','No account',lang),bi('Профиль необязателен.','The profile is optional.',lang)],
 [icon('lock'),bi('Локальные данные','Local data',lang),bi('Хранятся в браузере.','Stored in your browser.',lang)],
 [icon('calculators'),bi('Открытые формулы','Open formulas',lang),bi('Допущения видны.','Assumptions are visible.',lang)],
 [icon('evidence'),bi('Слой доказательности','Evidence layer',lang),bi('Метод и основание разделены.','Method and evidence are separate.',lang)],
 [icon('chart'),bi('Честная динамика','Honest trends',lang),bi('Без выдуманного сглаживания.','No invented smoothing.',lang)],
 [icon('insights'),bi('Без магических оценок','No magic scores',lang),bi('Только прозрачные правила.','Only transparent rules.',lang)]
];

function heroVisual(lang){return `<div class="hero-visual" aria-label="${bi('Схема: данные превращаются в расчёт, контекст и динамику','Diagram: data becomes calculation, context and trend',lang)}" role="img"><svg viewBox="0 0 560 430"><defs><linearGradient id="line" x1="0" x2="1"><stop stop-color="#79e2b8"/><stop offset="1" stop-color="#d5b96d"/></linearGradient></defs><g class="grid-lines"><path d="M30 55H530M30 115H530M30 175H530M30 235H530M30 295H530M30 355H530M90 25V405M170 25V405M250 25V405M330 25V405M410 25V405M490 25V405"/></g><circle class="orbit o1" cx="280" cy="210" r="145"/><circle class="orbit o2" cx="280" cy="210" r="98"/><path class="trend-line" d="M76 302c70-8 82-67 143-53s67-71 125-43 79-38 138-71"/><g class="hero-node n1"><circle cx="102" cy="302" r="34"/><path d="M94 310v-18l8 9 8-9v18"/></g><g class="hero-node n2"><rect x="244" y="175" width="72" height="72" rx="18"/><text x="280" y="205">24.7</text><text x="280" y="225">kg/m²</text></g><g class="hero-node n3"><circle cx="458" cy="138" r="34"/><path d="m444 140 9 9 18-22"/></g><g class="metric-label ml1"><rect x="42" y="74" width="136" height="54" rx="14"/><text x="58" y="96">${bi("ЛОКАЛЬНЫЙ ПРОФИЛЬ","LOCAL PROFILE",lang)}</text><text x="58" y="114">${bi("приватно по умолчанию","private by default",lang)}</text></g><g class="metric-label ml2"><rect x="352" y="296" width="158" height="58" rx="14"/><text x="368" y="319">${bi("МЕТОД × ОСНОВАНИЕ","METHOD × EVIDENCE",lang)}</text><text x="368" y="338">${bi("видимая неопределённость","visible uncertainty",lang)}</text></g></svg></div>`}

function homeDashboard(state,lang){
 const recent=state.recents.map(id=>calculatorMap.get(id)).filter(Boolean).slice(0,3),latest=state.history.at(-1),favorite=state.favorites.map(id=>calculatorMap.get(id)).find(Boolean),recommendation=getRecommendations(state.profile)[0];
 if(!recent.length&&!latest&&!favorite&&!recommendation)return'';
 const next=calculatorMap.get(recommendation?.target)||favorite||recent[0];
 return `<section class="personal-dashboard" aria-labelledby="dashboard-title"><header><div><span class="eyebrow">${bi('ВАШЕ ПРОДОЛЖЕНИЕ','CONTINUE',lang)}</span><h2 id="dashboard-title">${bi('Вернитесь к измеримому контексту','Return to measurable context',lang)}</h2></div><a class="text-action" href="#insights">${bi('История и динамика','History and trends',lang)} ${icon('arrow')}</a></header><div class="dashboard-grid">${latest?`<article class="dashboard-result"><span>${bi('Последний сохранённый результат','Latest saved result',lang)}</span><strong>${esc(latest.summary)}</strong><a href="#calc/${esc(latest.calcId)}">${esc(l(calculatorMap.get(latest.calcId)?.title,lang))} ${icon('arrow')}</a></article>`:''}${next?`<article><span>${bi('Следующий полезный шаг','Useful next step',lang)}</span><strong>${esc(l(next.title,lang))}</strong><p>${esc(recommendation?l(recommendation.why,lang):l(next.description,lang))}</p><a class="btn" href="#calc/${next.id}">${bi('Открыть расчёт','Open calculator',lang)}</a></article>`:''}${recent.length?`<article><span>${bi('Недавно использовали','Recently used',lang)}</span><div class="dashboard-links">${recent.map(calc=>`<a href="#calc/${calc.id}">${icon(calc.category)}<span>${esc(l(calc.title,lang))}</span></a>`).join('')}</div></article>`:''}</div></section>`;
}

export function home(state){const lang=state.lang,completion=Math.round(profileKeys.filter(k=>state.profile[k]!==undefined&&state.profile[k]!=='').length/profileKeys.length*100),recs=getRecommendations(state.profile);return `<section class="hero"><div class="hero-copy"><span class="eyebrow dot">${t('heroBadge',lang)}</span><h1>${t('heroTitle',lang)}</h1><p>${t('heroText',lang)}</p><div class="hero-actions"><a class="btn primary" href="#profile">${t('fillProfile',lang)} ${icon('arrow')}</a><a class="btn" href="#calculators">${t('openTools',lang)}</a><button class="text-action" data-action="palette">${icon('search')} ${t('search',lang)}</button></div><div class="hero-proof"><span>${icon('lock')} ${t('privacyNote',lang)}</span><span>${CALCULATORS.length} ${t('tools',lang)}</span><span>9 ${t('domains',lang)}</span></div></div>${heroVisual(lang)}</section>
 ${homeDashboard(state,lang)}
 <section class="principles" aria-label="${t('trust',lang)}">${principles(lang).map(([i,h,p])=>`<article>${i}<div><strong>${h}</strong><span>${p}</span></div></article>`).join('')}</section>
 <section>${sectionHead(bi("01 / ПРОЦЕСС","01 / FLOW",lang),t('howWorks',lang),t('chain',lang))}<ol class="flow-list">${[bi('Введите данные','Enter data',lang),bi('Получите расчёт','Get a calculation',lang),bi('Поймите смысл','Understand meaning',lang),bi('Сверьте основание','Review evidence',lang),bi('Учтите ограничение','Consider limitation',lang),bi('Выберите действие','Choose an action',lang),bi('Следите за динамикой','Track the trend',lang)].map((x,i)=>`<li><b>${String(i+1).padStart(2,'0')}</b><span>${x}</span></li>`).join('')}</ol></section>
 <section>${sectionHead(bi("02 / НАПРАВЛЕНИЯ","02 / DOMAINS",lang),t('labs',lang),bi('Каждая лаборатория отвечает на практический вопрос.','Each laboratory answers a practical question.',lang))}<div class="labs-grid">${Object.entries(categories).map(([id,c])=>`<a class="lab-card domain-${id}" href="#category/${id}"><span class="lab-icon">${icon(id)}</span><div><h3>${esc(l(c,lang))}</h3><p>${esc(l(c.question,lang))}</p><small>${count(id)} ${t('tools',lang)} ${icon('arrow')}</small></div><span class="lab-graph" aria-hidden="true"></span></a>`).join('')}</div></section>
 <section>${sectionHead(bi("03 / ПЕРВЫЙ ПОРЯДОК","03 / HIGH UTILITY",lang),t('featured',lang),bi('Быстрые точки входа с высоким практическим ROI.','High-ROI starting points.',lang))}<div class="tools-grid">${CALCULATORS.filter(c=>c.featured).slice(0,6).map(c=>toolCard(c,state)).join('')}</div><div class="center-action"><a class="btn" href="#calculators">${t('openTools',lang)} ${icon('arrow')}</a></div></section>
 <section class="feature-split"><article class="feature-panel profile-feature"><span class="eyebrow">${bi("04 / ПРОФИЛЬ","04 / PROFILE",lang)}</span><h2>${t('profilePayoff',lang)}</h2><p>${t('profileIntro',lang)}</p><div class="completion-ring" style="--value:${completion}"><b>${completion}%</b><span>${t('completion',lang)}</span></div><a class="btn primary" href="#profile">${t('fillProfile',lang)} ${icon('arrow')}</a></article><article class="feature-panel insights-feature"><span class="eyebrow">${bi("05 / ВЫВОДЫ","05 / INSIGHTS",lang)}</span><h2>${t('transparentRules',lang)}</h2><p>${t('insightsExplain',lang)}</p>${recs.length?recs.slice(0,2).map((r,i)=>insightCard(r,i,lang,true,state.profile)).join(''):`<div class="mini-empty">${t('noInsights',lang)}</div>`}<a class="btn" href="#insights">${t('insights',lang)} ${icon('arrow')}</a></article></section>
 <section class="progress-showcase"><div><span class="eyebrow">${bi("06 / ДИНАМИКА","06 / PROGRESS",lang)}</span><h2>${t('progress',lang)}</h2><p>${t('progressText',lang)}</p><ul class="check-list"><li>${icon('check')}${bi('Снимки ключевых показателей','Key metric snapshots',lang)}</li><li>${icon('check')}${bi('Сравнение с предыдущим значением','Previous-value comparison',lang)}</li><li>${icon('check')}${bi('Доступные SVG-графики','Accessible SVG charts',lang)}</li></ul></div>${sampleChart(lang)}</section>
 <section class="evidence-showcase"><div><span class="eyebrow">${bi("07 / ОСНОВАНИЯ","07 / EVIDENCE",lang)}</span><h2>${t('evidenceTitle',lang)}</h2><p>${t('methodLegend',lang)}</p><a class="btn" href="#evidence">${t('evidence',lang)} ${icon('arrow')}</a></div><div class="matrix" aria-label="Method type by evidence strength"><div></div><b>${bi('Высокая','High',lang)}</b><b>${bi('Умеренная','Moderate',lang)}</b><b>${bi('Ограниченная','Limited',lang)}</b><b>${bi('Математика','Math',lang)}</b><i class="on"></i><i class="on"></i><i></i><b>${bi('Оценка','Estimate',lang)}</b><i class="on"></i><i class="on"></i><i class="on"></i><b>${bi('Эвристика','Heuristic',lang)}</b><i></i><i class="on"></i><i class="on"></i></div></section>
 <section class="privacy-banner"><div class="privacy-orbit">${icon('lock')}</div><div><span class="eyebrow">${bi("08 / ПРИВАТНОСТЬ","08 / PRIVATE BY DEFAULT",lang)}</span><h2>${t('privacyHero',lang)}</h2><p>${bi('localStorage означает: данные живут в браузере этого устройства. Экспорт — обычный JSON. Очистка данных браузера может удалить профиль, поэтому для переноса используйте экспорт.','localStorage means data lives in this browser on this device. Export is plain JSON. Clearing browser data can remove the profile, so use export when moving devices.',lang)}</p></div><a class="btn" href="#about">${t('about',lang)} ${icon('arrow')}</a></section>
 <section>${sectionHead(bi("09 / ВОПРОСЫ","09 / FAQ",lang),t('faq',lang))}<div class="faq-grid">${faq(lang)}</div></section>
 <section class="final-cta"><span class="eyebrow">MARKOVLAB</span><h2>${bi('Начните с одного измеримого вопроса.','Start with one measurable question.',lang)}</h2><p>${bi('Профиль ускоряет работу, но не обязателен.','The profile speeds things up, but remains optional.',lang)}</p><div><a class="btn primary" href="#profile">${t('startProfile',lang)}</a><a class="btn" href="#calculators">${t('openTools',lang)}</a></div></section>`}

function faq(lang){const xs=lang==='ru'?[['MARKOVLAB ставит диагноз?','Нет. Скрининги и оценки показывают контекст, но не заменяют обследование.'],['Куда отправляются данные?','Никуда. Они сохраняются в локальном хранилище текущего браузера.'],['Почему метод и доказательность разделены?','Качественный источник может поддерживать формулу, но формула всё равно ошибаться для конкретного человека.'],['Можно работать без профиля?','Да. Профиль нужен только для автозаполнения.'],['Что доступно офлайн?','После первого успешного открытия приложение и основные данные сохраняются на устройстве.'],['Есть ли общая оценка здоровья?','Нет. Она скрывала бы допущения и создавала ложную точность.']]:[['Does MARKOVLAB diagnose?','No. Screenings and estimates provide context but do not replace assessment.'],['Where does data go?','Nowhere. It is stored in this browser’s localStorage.'],['Why separate method and evidence?','A strong source can support an equation while individual prediction error remains large.'],['Can I work without a profile?','Yes. The profile only enables prefill.'],['What works offline?','After the first successful visit, the app shell and core data are cached locally.'],['Is there an overall health score?','No. It would hide assumptions and create false precision.']];return xs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}

export function calculatorsPage(state,query='',favoritesOnly=false){const lang=state.lang,q=query.trim(),favoriteSet=favoritesOnly?new Set(state.favorites):null,list=searchCalculators(CALCULATORS,q,{favorites:favoriteSet});return `<header class="page-head library-head"><span class="eyebrow">${bi("86 ИНСТРУМЕНТОВ / 9 НАПРАВЛЕНИЙ","86 TOOLS / 9 DOMAINS",lang)}</span><h1>${t('calculators',lang)}</h1><p>${bi('Опишите задачу обычными словами — название формулы знать не обязательно.','Describe the task in plain language — you do not need to know the formula name.',lang)}</p></header><div class="search-panel">${icon('search')}<input class="library-search" id="library-search" type="search" value="${esc(query)}" placeholder="${t('searchPlaceholder',lang)}" aria-label="${t('search',lang)}"><button class="icon-btn" data-action="clear-library-search" aria-label="${t('clearSearch',lang)}">${icon('close')}</button></div><div class="intent-examples" aria-label="${bi('Примеры запросов','Example searches',lang)}">${(lang==='ru'?['сколько калорий мне есть','процент жира','максимум в жиме','темп бега']:['how many calories should I eat','body fat','one rep max','running pace']).map(x=>`<button data-action="intent-search" data-search-query="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="filters"><button class="chip ${!favoritesOnly?'active':''}" data-filter="all">${t('all',lang)} <span>${CALCULATORS.length}</span></button><button class="chip ${favoritesOnly?'active':''}" data-filter="favorites">${icon('star')} ${t('favorites',lang)} <span>${state.favorites.length}</span></button>${Object.entries(categories).map(([id,c])=>`<a class="chip" href="#category/${id}">${icon(id)} ${esc(l(c,lang))}</a>`).join('')}</div><div id="library-results">${libraryResults(state,q,list,favoritesOnly)}</div>`}

function libraryResults(state,q,list,favoritesOnly){const lang=state.lang;if(!list.length)return `<div class="empty-state">${icon(favoritesOnly?'star':'search')}<h2>${favoritesOnly?t('noFavorites',lang):t('noResults',lang)}</h2><p>${bi('Измените запрос или откройте все инструменты.','Change the query or open all tools.',lang)}</p><button class="btn" data-filter="all">${t('all',lang)}</button></div>`;if(q||favoritesOnly)return `<div class="results-summary"><strong>${list.length}</strong><span>${bi('подходящих инструментов','matching tools',lang)}</span></div><div class="tools-grid">${list.map(c=>toolCard(c,state)).join('')}</div>`;const recent=state.recents.map(id=>calculatorMap.get(id)).filter(Boolean).slice(0,4),featured=CALCULATORS.filter(c=>c.featured).slice(0,6);return `${recent.length?`<section class="library-shelf"><header><span class="eyebrow">${bi('НЕДАВНО','RECENT',lang)}</span><h2>${bi('Продолжить работу','Continue where you left off',lang)}</h2></header><div class="tools-grid compact">${recent.map(c=>toolCard(c,state)).join('')}</div></section>`:''}<section class="library-shelf"><header><span class="eyebrow">${bi('ПЕРВЫЙ ПОРЯДОК','HIGH UTILITY',lang)}</span><h2>${bi('Начните с этих расчётов','Start with these calculations',lang)}</h2></header><div class="tools-grid">${featured.map(c=>toolCard(c,state)).join('')}</div></section><section class="library-shelf"><header><span class="eyebrow">${bi('ПО НАПРАВЛЕНИЯМ','BY DOMAIN',lang)}</span><h2>${bi('Девять лабораторий','Nine laboratories',lang)}</h2></header><div class="domain-index">${Object.entries(categories).map(([id,c])=>`<a href="#category/${id}"><span>${icon(id)}</span><div><strong>${esc(l(c,lang))}</strong><small>${esc(l(c.question,lang))}</small></div><b>${count(id)}</b></a>`).join('')}</div></section>`}

export function categoryPage(state,id){const lang=state.lang,c=categories[id];if(!c)return notFoundPage(state);const list=CALCULATORS.filter(x=>x.category===id),featured=list.filter(x=>x.featured).slice(0,4),others=featured.length?list.filter(x=>!featured.includes(x)):list;return `<header class="category-hero domain-${id}"><div><a class="back-link" href="#calculators">${icon('arrow')} ${t('calculators',lang)}</a><span class="category-symbol">${icon(id)}</span><span class="eyebrow">${count(id)} ${t('tools',lang)}</span><h1>${esc(l(c,lang))}</h1><p>${esc(l(c.intro,lang))}</p></div><div class="category-illustration" aria-hidden="true">${domainIllustration(id)}</div></header><section class="category-info"><article><span class="eyebrow">${t('categoryWhat',lang)}</span><h2>${esc(l(c.question,lang))}</h2><p>${bi('Сочетайте несколько показателей и смотрите на динамику: одиночное значение редко достаточно для решения.','Combine several metrics and look at trends: one value is rarely enough for a decision.',lang)}</p></article><article><span class="eyebrow">${t('limitations',lang)}</span><h2>${bi('Не путайте оценку с измерением','Do not confuse estimate with measurement',lang)}</h2><p>${bi('Полевые формулы удобны, но их индивидуальная ошибка может быть существенной. Контекст метода всегда виден в результате.','Field equations are useful, but individual error may be material. Method context is always visible in the result.',lang)}</p></article></section>${featured.length?`<section>${sectionHead(bi("РЕКОМЕНДОВАНО","CURATED",lang),bi('Начните здесь','Start here',lang),bi('Инструменты, которые чаще всего меняют практическое решение.','Tools most likely to change a practical decision.',lang))}<div class="tools-grid">${featured.map(x=>toolCard(x,state)).join('')}</div></section>`:''}<section>${sectionHead(bi("ВСЕ ИНСТРУМЕНТЫ","ALL TOOLS",lang),t('categoryTools',lang),`${list.length} ${t('tools',lang)}`)}<div class="tools-grid">${others.map(x=>toolCard(x,state)).join('')}</div></section><section>${sectionHead(bi("ПОСЛЕДОВАТЕЛЬНОСТИ","WORKFLOWS",lang),t('workflows',lang))}<div class="workflow-row">${list.slice(0,4).map((x,i)=>`<a href="#calc/${x.id}"><b>${String(i+1).padStart(2,'0')}</b><span>${esc(l(x.title,lang))}</span>${icon('arrow')}</a>`).join('')}</div></section><div class="related-domains">${Object.entries(categories).filter(([key])=>key!==id).slice(0,4).map(([key,x])=>`<a href="#category/${key}">${icon(key)}<span>${esc(l(x,lang))}</span></a>`).join('')}</div>`}

function fieldValue(f,state,session){if(session?.[f.id]!==undefined)return session[f.id];if(f.profileKey&&state.profile[f.profileKey]!==undefined)return state.profile[f.profileKey];return f.default??''}
function fromProfile(f,state,session){return session?.[f.id]===undefined&&f.profileKey&&state.profile[f.profileKey]!==undefined}
export function calculatorPage(calc,state,session,resultData,errors={}){const lang=state.lang;if(!calc)return notFoundPage(state);const isFav=state.favorites.includes(calc.id),related=CALCULATORS.filter(c=>c.category===calc.category&&c.id!==calc.id).slice(0,4);return `<nav class="breadcrumbs" aria-label="${bi('Хлебные крошки','Breadcrumbs',lang)}"><a href="#calculators">${t('calculators',lang)}</a><span>/</span><a href="#category/${calc.category}">${esc(l(categories[calc.category],lang))}</a><span>/</span><span aria-current="page">${esc(l(calc.title,lang))}</span></nav><header class="calc-head"><div class="calc-icon">${icon(calc.category)}</div><div class="calc-title"><span class="eyebrow">${esc(l(categories[calc.category],lang))}</span><h1>${esc(l(calc.title,lang))}</h1><p>${esc(l(calc.description,lang))}</p><div class="card-meta">${badge(calc,lang)}</div></div><button class="fav-btn standalone ${isFav?'active':''}" data-favorite="${calc.id}" aria-label="${t('favorite',lang)}" aria-pressed="${isFav}">${icon('star')}</button></header><section class="calc-explainer"><article><span>${icon('calculators')}</span><div><h2>${t('whatDoes',lang)}</h2><p>${esc(l(calc.description,lang))}</p></div></article><article><span>${icon('check')}</span><div><h2>${t('whenUseful',lang)}</h2><p>${bi('Когда число способно уточнить решение или задать точку отсчёта для динамики.','When a number can clarify a decision or create a baseline for a trend.',lang)}</p></div></article><article><span>${icon('profile')}</span><div><h2>${t('whatNeed',lang)}</h2><p>${calc.fields.map(f=>esc(l(f.label,lang))).join(' · ')}</p></div></article></section><div class="calc-grid"><form class="panel form-panel" id="calc-form" data-calc="${calc.id}" novalidate>${Object.keys(errors).length?`<div class="error-summary" role="alert" tabindex="-1"><strong>${t('errorSummary',lang)}</strong><ul>${Object.entries(errors).map(([id,msg])=>`<li><a href="#${esc(id)}">${esc(msg)}</a></li>`).join('')}</ul></div>`:''}<div class="form-intro"><div><span class="eyebrow">${bi("ВВОД","INPUT",lang)}</span><h2>${bi('Данные расчёта','Calculation inputs',lang)}</h2></div><p>${t('localOverride',lang)}</p></div><div class="field-grid">${calc.fields.map(f=>fieldHtml(f,fieldValue(f,state,session),lang,errors[f.id],fromProfile(f,state,session))).join('')}</div><div class="form-actions"><button class="btn primary" type="submit" data-action="calculate">${t('calculate',lang)} ${icon('arrow')}</button><button class="btn" type="reset">${icon('reset')} ${t('reset',lang)}</button></div></form>${resultHtml(calc,resultData,state)}</div><section class="worked panel"><span class="eyebrow">${t('workedExample',lang)}</span>${workedExample(calc,state)}</section><section>${sectionHead(bi("ДАЛЬШЕ","NEXT",lang),t('related',lang),t('whyRelated',lang))}<div class="tools-grid compact">${related.map(c=>toolCard(c,state)).join('')}</div></section>`}

function fieldHtml(f,value,lang,error,prefilled){const id=`f-${f.id}`,desc=`hint-${f.id}`,err=`err-${f.id}`,unit=f.unit?`<span class="unit">${esc(f.unit)}</span>`:'';let control;if(f.type==='select')control=`<select id="${id}" name="${f.id}" aria-describedby="${desc} ${err}" ${error?'aria-invalid="true"':''}>${f.options.map(o=>`<option value="${esc(o.value)}" ${String(value)===String(o.value)?'selected':''}>${esc(l(o.label,lang))}</option>`).join('')}</select>`;else control=`<input id="${id}" name="${f.id}" type="${f.type}" value="${esc(value)}" ${f.type==='number'?'inputmode="decimal"':''} ${f.placeholder?`placeholder="${esc(f.placeholder)}"`:''} ${f.min!=null?`min="${f.min}"`:''} ${f.max!=null?`max="${f.max}"`:''} ${f.step!=null?`step="${f.step}"`:''} aria-describedby="${desc} ${err}" ${error?'aria-invalid="true"':''}>`;return `<div class="field"><div class="field-label"><label for="${id}">${esc(l(f.label,lang))}</label>${prefilled?`<span class="profile-chip">${icon('profile')} ${t('fromProfile',lang)}</span>`:''}</div><div class="input-wrap">${control}${unit}</div><small class="field-hint" id="${desc}">${prefilled?t('profileOverride',lang):f.min!=null&&f.max!=null?`${f.min}–${f.max}`:f.placeholder||t('optional',lang)}</small><span class="field-error" id="${err}">${esc(error||'')}</span></div>`}
function resultHtml(calc,r,state){const lang=state.lang;if(!r)return `<aside class="panel result-panel empty-result"><div class="empty-result-visual">${icon('chart')}</div><span class="eyebrow">${bi("РЕЗУЛЬТАТ","OUTPUT",lang)}</span><h2>${t('emptyResultTitle',lang)}</h2><p>${t('emptyResultText',lang)}</p><div class="result-skeleton" aria-hidden="true"><i></i><i></i><i></i></div></aside>`;const refs=calc.sources.map(id=>REFERENCES[id]).filter(Boolean);return `<aside class="panel result-panel" aria-live="polite"><div class="result-header"><div><span class="result-kicker">${t('result',lang)}</span><div class="result-value"><strong>${esc(typeof r.primary==='number'?formatNumber(r.primary,lang,2):r.primary)}</strong>${r.unit?`<span>${esc(r.unit)}</span>`:''}</div></div><div class="result-badges">${badge(calc,lang)}</div></div>${resultViz(r,lang)}${r.secondary?.length?`<div class="secondary-results">${r.secondary.map(x=>`<div class="secondary-item"><small>${esc(l(x.label,lang))}</small><b>${esc(x.value)} ${esc(x.unit||'')}</b></div>`).join('')}</div>`:''}<div class="result-sections"><section><span>${icon('calculators')}</span><div><h3>${t('context',lang)}</h3><p>${esc(l(r.interpretation,lang))}</p></div></section><section><span>${icon('evidence')}</span><div><h3>${t('confidence',lang)}</h3><p>${esc(l(r.confidence,lang))}</p></div></section><section class="limitation"><span>${icon('about')}</span><div><h3>${t('limitation',lang)}</h3><p>${esc(l(r.limitation,lang))}</p></div></section><section class="action"><span>${icon('arrow')}</span><div><h3>${t('action',lang)}</h3><p>${esc(l(r.action,lang))}</p></div></section></div><details class="formula-details"><summary>${icon('calculators')} ${t('formula',lang)}</summary><div><p class="formula-line">${esc(l(r.assumptions?.[0],lang))}</p>${refs.length?`<div class="source-list">${refs.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer"><span>${esc(l(s.title,lang))}</span>${icon('external')}</a>`).join('')}</div>`:`<p>${bi('Чистая арифметика; внешний источник не требуется.','Pure arithmetic; no external source required.',lang)}</p>`}</div></details><div class="result-actions"><button class="btn" data-action="save-result">${icon('check')} ${t('saveResult',lang)}</button><button class="btn" data-action="copy-result">${icon('copy')} ${t('copyResult',lang)}</button><button class="btn" data-action="print">${icon('print')} ${t('printReport',lang)}</button></div>${['body','energy','nutrition','cardio','recovery'].includes(calc.category)?`<p class="medical-note">${icon('about')} ${t('medical',lang)}</p>`:''}</aside>`}
function resultViz(){return''}
function workedExample(calc,state){const lang=state.lang;try{const values=Object.fromEntries(calc.fields.map(f=>[f.id,f.default])),r=calc.calculate(values,{profile:{}}),formatValue=f=>f.type==='select'?l(f.options.find(option=>String(option.value)===String(f.default))?.label,lang):f.default;return `<h2>${calc.fields.slice(0,4).map(f=>`${esc(l(f.label,lang))}: <b>${esc(formatValue(f))}${f.unit?` ${esc(f.unit)}`:''}</b>`).join(' · ')}</h2><p>${icon('arrow')} <strong>${esc(r.primary)}${r.unit?` ${esc(r.unit)}`:''}</strong></p><small>${esc(l(r.assumptions?.[0],lang))}</small>`}catch{return `<p>${bi('Используйте значения по умолчанию как демонстрационный сценарий.','Use the default values as a demonstration scenario.',lang)}</p>`}}

const profileSections=[['basic','Basic',['age','sex','height','weight']],['body','Body',['waist','hip','neck','bodyFat']],['activity','Activity',['restingHR','steps','moderateMinutes','vigorousMinutes','strengthDays']],['recovery','Recovery',['sleepHours','caffeineDaily','subjectiveStress']],['goals','Goals',['primaryGoal']],['finance','Finance',['income','savings','expenses','emergencyCash']]];
const pf={age:['Возраст','Age','years',14,110],sex:['Пол','Sex','',null,null],height:['Рост','Height','cm',80,250],weight:['Вес','Weight','kg',20,500],waist:['Талия','Waist','cm',30,300],hip:['Бёдра','Hips','cm',30,300],neck:['Шея','Neck','cm',15,100],bodyFat:['Процент жира','Body fat','%',1,75],restingHR:['Пульс покоя','Resting HR','bpm',25,180],steps:['Шагов в день','Daily steps','',0,100000],moderateMinutes:['Умеренные минуты/нед','Moderate min/week','min',0,3000],vigorousMinutes:['Интенсивные минуты/нед','Vigorous min/week','min',0,2000],strengthDays:['Силовых дней/нед','Strength days/week','',0,14],sleepHours:['Сон','Sleep','h',0,24],caffeineDaily:['Кофеин в день','Daily caffeine','mg',0,3000],subjectiveStress:['Стресс 0–5','Stress 0–5','',0,5],primaryGoal:['Основная цель','Primary goal','',null,null],income:['Доход в месяц','Monthly income','',0,1e12],savings:['Сбережения в месяц','Monthly savings','',-1e12,1e12],expenses:['Расходы в месяц','Monthly expenses','',0,1e12],emergencyCash:['Ликвидный резерв','Liquid reserve','',0,1e15]};
export function profilePage(state){const lang=state.lang,done=profileKeys.filter(k=>state.profile[k]!==undefined&&state.profile[k]!=='').length,pct=Math.round(done/profileKeys.length*100);return `<header class="page-head profile-head"><div><span class="eyebrow">${bi("ЛОКАЛЬНО / НЕОБЯЗАТЕЛЬНО","LOCAL / OPTIONAL",lang)}</span><h1>${t('profile',lang)}</h1><p>${t('profileIntro',lang)}</p></div><div class="profile-progress"><div class="completion-ring" style="--value:${pct}"><b>${pct}%</b><span>${done}/${profileKeys.length}</span></div><div><strong>${t('completion',lang)}</strong><span>${t('privacyNote',lang)}</span></div></div></header><div class="privacy-callout">${icon('lock')}<div><strong>${t('privacyHero',lang)}</strong><span>${t('privacyText',lang)}</span></div></div><form id="profile-form" class="profile-form">${profileSections.map(([id,name,keys],index)=>profileSection(id,name,keys,index,state,lang)).join('')}<div class="sticky-form-actions"><button class="btn primary" type="submit">${t('saveProfile',lang)}</button><button class="btn" type="button" data-action="snapshot">${icon('chart')} ${t('saveSnapshot',lang)}</button><button class="btn danger" type="button" data-action="clear-profile">${icon('close')} ${t('clearProfile',lang)}</button></div></form>`}
function profileSection(id,name,keys,index,state,lang){const labels={basic:['Основное','Basic'],body:['Тело','Body'],activity:['Активность','Activity'],recovery:['Восстановление','Recovery'],goals:['Цели','Goals'],finance:['Финансы','Finance']};const done=keys.filter(k=>state.profile[k]!==undefined&&state.profile[k]!=='').length,open=index===0?' open':'';return `<details class="profile-section panel"${open}><summary><header><div class="section-number">${String(index+1).padStart(2,'0')}</div><div><h2>${labels[id][lang==='ru'?0:1]}</h2><p>${done}/${keys.length} ${bi('заполнено','complete',lang)}</p></div><span class="section-status">${done===keys.length?icon('check'):`${done}/${keys.length}`}</span></header><span class="profile-section-toggle" aria-hidden="true">${bi('Показать поля','Show fields',lang)}</span></summary><div class="profile-grid">${keys.map(k=>profileField(k,state,lang)).join('')}</div></details>`}
function profileField(id,state,lang){const [ru,en,unit,min,max]=pf[id],value=state.profile[id]??'';let c;if(id==='sex')c=`<select id="p-${id}" name="${id}"><option value="">—</option><option value="male" ${value==='male'?'selected':''}>${bi('Мужской','Male',lang)}</option><option value="female" ${value==='female'?'selected':''}>${bi('Женский','Female',lang)}</option></select>`;else if(id==='primaryGoal')c=`<select id="p-${id}" name="${id}"><option value="">—</option>${['health','fat-loss','muscle','performance','finance'].map(x=>`<option value="${x}" ${value===x?'selected':''}>${t(`goal_${x.replace('-','_')}`,lang)}</option>`).join('')}</select>`;else c=`<input id="p-${id}" name="${id}" type="number" inputmode="decimal" value="${esc(value)}" ${min!=null?`min="${min}"`:''} ${max!=null?`max="${max}"`:''} step="any">`;return `<div class="field"><div class="field-label"><label for="p-${id}">${esc(lang==='ru'?ru:en)}</label><span>${t('optional',lang)}</span></div><div class="input-wrap">${c}${unit?`<span class="unit">${formatUnit(unit,lang)}</span>`:''}</div></div>`}

function insightCard(r,i,lang,mini=false,profile={}){const trigger=triggerData(r.id,profile,lang);return `<article class="insight-card ${mini?'mini':''}"><div class="insight-rank">${String(i+1).padStart(2,'0')}</div><div><span class="eyebrow">${t('transparentRules',lang)} · P${Math.ceil(r.priority/20)}</span><h3>${esc(l(r.title,lang))}</h3><p>${esc(l(r.why,lang))}</p>${!mini?`<small>${bi('Сработало на данных','Triggered by',lang)}: ${esc(trigger)} · ${bi('источник','source',lang)}: ${esc(r.source||bi('арифметика профиля','profile arithmetic',lang))}</small>`:''}</div><a class="btn" href="#calc/${r.target}">${t('reopen',lang)} ${icon('arrow')}</a></article>`}
function triggerData(id,p,lang){const unit=value=>formatUnit(value,lang),map={sleep:`${bi('Сон','Sleep',lang)}: ${p.sleepHours??'—'} ${unit('h')}`,activity:`${bi('Активность','Activity',lang)}: ${(Number(p.moderateMinutes)||0)+2*(Number(p.vigorousMinutes)||0)} ${unit('min')}`,strength:`${bi('Силовые дни','Strength days',lang)}: ${p.strengthDays??'—'}`,waist:`WHtR: ${p.waist&&p.height?(Number(p.waist)/Number(p.height)).toFixed(2):'—'}`,caffeine:`${bi('Кофеин','Caffeine',lang)}: ${p.caffeineDaily??'—'} ${unit('mg')}`,protein:`${bi('Вес','Weight',lang)}: ${p.weight??'—'} ${unit('kg')}`,runway:`${bi('Резерв / расходы','Cash / expenses',lang)}: ${p.emergencyCash??'—'} / ${p.expenses??'—'}`};return map[id]||bi('Поля профиля','Profile fields',lang)}
export function insightsPage(state,historyQuery='',sort='newest'){const lang=state.lang,recs=getRecommendations(state.profile),history=[...state.history].filter(x=>!historyQuery||`${l(calculatorMap.get(x.calcId)?.title,'ru')} ${l(calculatorMap.get(x.calcId)?.title,'en')} ${x.summary}`.toLowerCase().includes(historyQuery.toLowerCase())).sort((a,b)=>(sort==='oldest'?1:-1)*(Date.parse(a.at)-Date.parse(b.at)));return `<header class="page-head"><span class="eyebrow">${t('transparentRules',lang)}</span><h1>${t('insights',lang)}</h1><p>${t('insightsExplain',lang)}</p></header>${recs.length?`<div class="insight-list">${recs.map((r,i)=>insightCard(r,i,lang,false,state.profile)).join('')}</div>`:`<div class="empty-state">${icon('insights')}<h2>${t('noInsights',lang)}</h2><a class="btn primary" href="#profile">${t('fillProfile',lang)}</a></div>`}<section>${sectionHead(bi("ИСТОРИЯ","HISTORY",lang),t('recent',lang),`${state.history.length} ${t('saved',lang)}`)}<div class="history-toolbar"><div class="search-panel">${icon('search')}<input id="history-search" value="${esc(historyQuery)}" placeholder="${t('historySearch',lang)}"></div><select id="history-sort" aria-label="${bi("Сортировка","Sort",lang)}"><option value="newest" ${sort==='newest'?'selected':''}>${t('sortNewest',lang)}</option><option value="oldest" ${sort==='oldest'?'selected':''}>${t('sortOldest',lang)}</option></select>${state.history.length?`<button class="btn danger" data-action="clear-history">${t('clearHistory',lang)}</button>`:''}</div><div id="history-results">${historyList(history,state)}</div></section><section>${sectionHead(bi("ДИНАМИКА","TRENDS",lang),t('snapshots',lang),`${state.snapshots.length} ${bi('снимков','snapshots',lang)}`)}${trends(state)}</section>`}
function historyList(items,state){const lang=state.lang;if(!items.length)return `<div class="empty-state">${icon('chart')}<h2>${t('noHistory',lang)}</h2><a class="btn" href="#calculators">${t('openTools',lang)}</a></div>`;return `<div class="history-list">${items.map(x=>`<article class="history-item"><span class="domain-icon">${icon(calculatorMap.get(x.calcId)?.category||'calculators')}</span><div><strong>${esc(l(calculatorMap.get(x.calcId)?.title||x.calcId,lang))}</strong><span>${esc(x.summary)}</span><small>${new Date(x.at).toLocaleString(lang==='ru'?'ru-RU':'en-US')}</small></div><div class="history-actions"><button class="btn" data-reopen-history="${esc(x.id)}">${t('recalculate',lang)}</button><button class="icon-btn danger" data-delete-history="${esc(x.id)}" aria-label="${t('delete',lang)}">${icon('close')}</button></div></article>`).join('')}</div>`}
function trends(state){const lang=state.lang,metrics=[['weight',bi('Вес','Weight',lang),'kg'],['waist',bi('Талия','Waist',lang),'cm'],['sleepHours',bi('Сон','Sleep',lang),'h'],['restingHR',bi('Пульс покоя','Resting HR',lang),'bpm'],['steps',bi('Шаги','Steps',lang),'']];const cards=metrics.map(([key,label,unit])=>trendCard(state.snapshots,key,label,unit,lang)).filter(Boolean);return cards.length?`<div class="trend-grid">${cards.join('')}</div>`:`<div class="empty-state">${icon('chart')}<h2>${t('noSnapshots',lang)}</h2><p>${t('needTwo',lang)}</p><a class="btn primary" href="#profile">${t('fillProfile',lang)}</a></div>`}
function trendCard(snaps,key,label,unit,lang){const data=snaps.map(s=>({at:s.at,value:Number(s.profile?.[key])})).filter(x=>Number.isFinite(x.value));if(!data.length)return'';const last=data.at(-1),prev=data.at(-2),diff=prev?last.value-prev.value:null;return `<article class="trend-card panel"><header><div><span class="eyebrow">${t('trend',lang)}</span><h3>${label}</h3></div><strong>${formatNumber(last.value,lang,1)} <small>${unit}</small></strong></header>${data.length>=2?lineChart(data,label,lang):`<div class="trend-empty">${t('needTwo',lang)}</div>`}<dl><div><dt>${t('current',lang)}</dt><dd>${formatNumber(last.value,lang,1)} ${unit}</dd></div><div><dt>${t('previous',lang)}</dt><dd>${prev?`${formatNumber(prev.value,lang,1)} ${unit}`:'—'}</dd></div><div><dt>${t('difference',lang)}</dt><dd>${diff==null?'—':`${diff>0?'+':''}${formatNumber(diff,lang,1)} ${unit}`}</dd></div></dl></article>`}
function lineChart(data,label,lang){const w=480,h=190,left=44,right=16,top=24,bottom=46,plotBottom=h-bottom,min=Math.min(...data.map(x=>x.value)),max=Math.max(...data.map(x=>x.value)),span=max-min||1,points=data.map((x,i)=>`${left+i*(w-left-right)/Math.max(1,data.length-1)},${plotBottom-(x.value-min)/span*(plotBottom-top)}`).join(' '),locale=lang==='ru'?'ru-RU':'en-US',date=x=>new Date(x.at).toLocaleDateString(locale,{day:'numeric',month:'short'});return `<svg class="line-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}: ${data.map(x=>`${date(x)} ${formatNumber(x.value,lang,1)}`).join(', ')}"><path class="axis" d="M${left} ${top}V${plotBottom}H${w-right}"/><polyline points="${points}"/><g>${data.map((x,i)=>{const [cx,cy]=points.split(' ')[i].split(',');return `<circle cx="${cx}" cy="${cy}" r="5" tabindex="0"><title>${new Date(x.at).toLocaleDateString(locale)}: ${formatNumber(x.value,lang,1)}</title></circle>`}).join('')}</g><text x="3" y="${top+4}">${formatNumber(max,lang,1)}</text><text x="3" y="${plotBottom+4}">${formatNumber(min,lang,1)}</text><text class="date-label" x="${left}" y="${h-10}">${date(data[0])}</text><text class="date-label" x="${w-right}" y="${h-10}" text-anchor="end">${date(data.at(-1))}</text></svg>`}

export function evidencePage(state,query=''){const lang=state.lang,q=query.toLowerCase();const refs=Object.entries(REFERENCES).filter(([,s])=>!q||[l(s.title,'ru'),l(s.title,'en'),l(s.type,'ru'),l(s.type,'en'),s.year].join(' ').toLowerCase().includes(q));return `<header class="page-head evidence-head"><span class="eyebrow">${bi("МЕТОД × ОСНОВАНИЕ","METHOD × EVIDENCE",lang)}</span><h1>${t('evidence',lang)}</h1><p>${t('methodLegend',lang)}</p></header><div class="evidence-axis"><section><span class="eyebrow">${bi("МЕТОД 01","METHOD 01",lang)}</span><h2>${t('method',lang)}</h2><div>${Object.entries(methodLabels).map(([id,x])=>`<article><span class="badge method">${esc(l(x,lang))}</span><p>${methodDescription(id,lang)}</p></article>`).join('')}</div></section><section><span class="eyebrow">${bi("ОСНОВАНИЕ 02","EVIDENCE BASIS 02",lang)}</span><h2>${t('strength',lang)}</h2><div>${Object.entries(evidenceLabels).map(([id,x])=>`<article><span class="badge evidence-${id}">${esc(l(x,lang))}</span><p>${evidenceDescription(id,lang)}</p></article>`).join('')}</div></section></div><div class="principle-note">${icon('about')}<strong>${bi('Сильное основание формулы не означает точный индивидуальный прогноз.','Strong evidence for an equation does not imply precise individual prediction.',lang)}</strong></div><section>${sectionHead(bi("БИБЛИОТЕКА ИСТОЧНИКОВ","SOURCE LIBRARY",lang),t('sources',lang),`${refs.length} ${bi('источников','sources',lang)}`)}<div class="search-panel evidence-search">${icon('search')}<input id="evidence-search" value="${esc(query)}" placeholder="${t('sourceSearch',lang)}"></div><div id="evidence-results" class="evidence-grid">${refs.map(([id,s])=>sourceCard(id,s,lang)).join('')}</div></section>`}
function sourceCard(id,s,lang){const used=CALCULATORS.filter(c=>c.sources.includes(id));return `<article class="evidence-card panel"><header><div><span class="source-marker">${s.primary?icon('check'):icon('evidence')}</span><span class="eyebrow">${s.year} · ${esc(l(s.type,lang))}</span></div><span class="badge">${s.primary?t('official',lang):bi('Вторичный','Secondary',lang)}</span></header><h3>${esc(l(s.title,lang))}</h3><p>${esc(l(s.note,lang))}</p><details><summary>${t('usedBy',lang)}: ${used.length}</summary><div class="used-by">${used.map(c=>`<a href="#calc/${c.id}">${esc(l(c.title,lang))}</a>`).join('')}</div></details><footer><small>${t('accessed',lang)}: ${esc(s.accessed)}</small><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${t('sources',lang)} ${icon('external')}</a></footer></article>`}
function methodDescription(id,lang){const m={math:['Чистая арифметика или конвертация.','Pure arithmetic or conversion.'],guideline:['Официальный ориентир, не персональная норма.','Official reference, not a personal prescription.'],'validated-estimate':['Опубликованное уравнение с индивидуальной ошибкой.','Published equation with individual error.'],screening:['Скрининговое отношение, не диагноз.','Screening ratio, not a diagnosis.'],heuristic:['Прозрачное практическое правило.','Transparent practical rule.'],experimental:['Предварительный метод.','Preliminary method.']};return m[id][lang==='ru'?0:1]}
function evidenceDescription(id,lang){const m={high:['Консенсус, официальное руководство или сильная валидация.','Consensus, official guidance or strong validation.'],moderate:['Полезная база с заметными ограничениями.','Useful foundation with meaningful limitations.'],limited:['Ограниченные или косвенные данные.','Limited or indirect evidence.'],experimental:['Предварительные данные; выводы нестабильны.','Preliminary evidence; conclusions are unstable.']};return m[id][lang==='ru'?0:1]}

export function aboutPage(state){const lang=state.lang;return `<header class="page-head about-head"><span class="eyebrow">MARKOVLAB / 2.0.0</span><h1>${t('about',lang)}</h1><p>${bi('Личная лаборатория измеримого прогресса: точная в арифметике, честная в неопределённости и приватная по архитектуре.','A personal laboratory for measurable progress: precise in arithmetic, honest about uncertainty and private by architecture.',lang)}</p></header><div class="about-grid"><article class="panel"><span class="eyebrow">${bi("ФИЛОСОФИЯ","PHILOSOPHY",lang)}</span><h2>${t('whyTrust',lang)}</h2><p>${t('chain',lang)}</p><p>${t('noMagic',lang)}</p></article><article class="panel"><span class="eyebrow">${bi("ПРИВАТНОСТЬ","PRIVACY",lang)}</span><h2>${t('privacyHero',lang)}</h2><p>${bi('Профиль и история находятся в локальном хранилище этого браузера. Сайт не содержит аналитики, трекеров, серверной части или скрытой синхронизации. На общем устройстве другие пользователи браузера могут получить доступ к локальным данным.','Profile and history live in localStorage. The site contains no analytics, trackers, backend or hidden sync. On a shared device, other browser users may access local data.',lang)}</p></article><article class="panel"><span class="eyebrow">${bi("ГРАНИЦЫ","BOUNDARY",lang)}</span><h2>${bi('Что продукт не делает','What the product does not do',lang)}</h2><p>${bi('Не ставит диагнозы, не назначает лечение, не выдаёт оценку за измерение и не создаёт общую оценку здоровья с помощью ИИ.','It does not diagnose, prescribe, present estimates as measurements or create an overall AI score.',lang)}</p></article><article class="panel"><span class="eyebrow">${bi("ОФЛАЙН","OFFLINE",lang)}</span><h2>PWA</h2><p>${bi('После первого открытия основные файлы доступны офлайн. Обновления применяются явно, когда новая версия готова.','After the first visit, core files work offline. Updates apply explicitly when a new version is ready.',lang)}</p><button class="btn" data-action="install" hidden>${t('install',lang)}</button></article></div><section class="prose panel"><h2>${t('methodology',lang)}</h2><ol><li>${bi('Сначала определите тип метода: арифметика, рекомендация, оценка, скрининг или эвристика.','First identify method type: math, guideline, estimate, screening or heuristic.',lang)}</li><li>${bi('Затем проверьте силу основания и главное ограничение.','Then review evidence strength and the main limitation.',lang)}</li><li>${bi('Округление соответствует реальной точности метода, а не технической возможности показать больше знаков.','Rounding reflects method precision, not JavaScript precision.',lang)}</li><li>${bi('Действуйте пропорционально уверенности и отслеживайте динамику.','Act in proportion to confidence and track the trend.',lang)}</li></ol><h2>${bi("История изменений","Changelog",lang)}</h2><p><strong>2.0.0</strong> — ${bi('новая система бренда, полноценные категории и калькуляторы, профиль по секциям, структурированная история, динамика, вводный экран, библиотека источников, жизненный цикл PWA и проверка доступности.','new brand system, full category and calculator pages, sectioned profile, structured history, trends, onboarding, evidence library, PWA lifecycle and accessibility pass.',lang)}</p><button class="btn" data-action="onboarding">${t('openOnboarding',lang)}</button><p class="doc-links"><a href="./README.md">${bi('Описание проекта','README',lang)} ${icon('external')}</a><a href="./docs/EVIDENCE.md">${bi('Политика доказательности','Evidence policy',lang)} ${icon('external')}</a><a href="./docs/FORMULAS.md">${bi('Справочник формул','Formula reference',lang)} ${icon('external')}</a></p></section>`}

export function notFoundPage(state){const lang=state.lang;return `<div class="empty-state not-found">${icon('search')}<span class="eyebrow">404</span><h1>${t('notFound',lang)}</h1><p>${bi('Маршрут не существует или инструмент был удалён.','The route does not exist or the tool was removed.',lang)}</p><a class="btn primary" href="#home">${t('goHome',lang)}</a></div>`}
export function onboarding(state,step=1){const lang=state.lang,steps=[{title:t('onboardingTitle',lang),text:t('onboardingText',lang),icon:'calculators'},{title:bi('Что хотите измерять?','What do you want to measure?',lang),text:bi('Начните с направления или опишите задачу в поиске. Формулу знать не нужно.','Start with a domain or describe your task in search. You do not need to know the formula.',lang),icon:'search'},{title:bi('Профиль — только для ускорения','The profile only saves time',lang),text:bi('Общие данные можно ввести один раз. Это необязательно, и всё остаётся в браузере.','Reusable data can be entered once. It is optional and stays in this browser.',lang),icon:'lock'}],current=steps[Math.max(0,Math.min(2,step-1))];return `<div class="onboarding-card" data-step="${step}"><button class="icon-btn onboarding-close" data-action="dismiss-onboarding" aria-label="${t('close',lang)}">${icon('close')}</button><div class="onboarding-visual">${logo(true)}<span>${icon(current.icon)}</span></div><div class="onboarding-progress" aria-label="${bi('Шаг','Step',lang)} ${step} ${bi('из','of',lang)} 3">${[1,2,3].map(x=>`<i class="${x<=step?'active':''}"></i>`).join('')}</div><span class="eyebrow">${bi(`ШАГ ${step} / 3`,`STEP ${step} / 3`,lang)}</span><h2>${current.title}</h2><p>${current.text}</p>${step===2?`<div class="onboarding-goals"><a href="#category/body" data-action="dismiss-onboarding">${icon('body')} ${l(categories.body,lang)}</a><a href="#category/nutrition" data-action="dismiss-onboarding">${icon('nutrition')} ${l(categories.nutrition,lang)}</a><a href="#category/strength" data-action="dismiss-onboarding">${icon('strength')} ${l(categories.strength,lang)}</a><a href="#category/money" data-action="dismiss-onboarding">${icon('money')} ${l(categories.money,lang)}</a></div>`:''}<div class="onboarding-actions">${step>1?`<button class="btn" data-onboarding-step="${step-1}">${bi('Назад','Back',lang)}</button>`:''}${step<3?`<button class="btn primary" data-onboarding-step="${step+1}">${bi('Далее','Next',lang)} ${icon('arrow')}</button>`:`<a class="btn primary" href="#profile" data-action="dismiss-onboarding">${t('fillProfile',lang)}</a>`}<button class="text-action" data-action="dismiss-onboarding">${t('continueNoProfile',lang)}</button></div></div>`}
export function paletteHtml(state,query='',activeIndex=0){const lang=state.lang,q=query.trim(),recent=state.recents.map(id=>calculatorMap.get(id)).filter(Boolean),items=(q?searchCalculators(CALCULATORS,q):recent.length?recent:CALCULATORS.filter(c=>c.featured)).slice(0,12);return `<div class="palette-head">${icon('search')}<input id="palette-search" placeholder="${t('searchPlaceholder',lang)}" value="${esc(query)}" autocomplete="off" aria-controls="palette-list"><button class="icon-btn" data-action="close-palette" aria-label="${t('close',lang)}">${icon('close')}</button></div><div class="palette-label">${q?t('search',lang):recent.length?t('recent',lang):t('featured',lang)}</div><div class="palette-list" id="palette-list" role="listbox">${items.length?items.map((c,i)=>`<button class="palette-item ${i===activeIndex?'active':''}" data-palette-id="${c.id}" role="option" aria-selected="${i===activeIndex}"><span class="lab-icon">${icon(c.category)}</span><span><strong>${highlight(l(c.title,lang),query)}</strong><small>${esc(l(categories[c.category],lang))} · ${highlight(l(c.description,lang),query)}</small></span><kbd>↵</kbd></button>`).join(''):`<div class="empty-state">${icon('search')}<h2>${t('noResults',lang)}</h2></div>`}</div>`}
function highlight(text,q){const safe=esc(text);if(!q)return safe;const needles=q.trim().split(/\s+/).filter(Boolean).map(token=>esc(token).replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));return needles.length?safe.replace(new RegExp(`(${needles.join('|')})`,'ig'),'<mark>$1</mark>'):safe}
function domainIllustration(id){const shapes={body:'<circle cx="110" cy="90" r="52"/><path d="M110 40v100M60 90h100M80 60l60 60M140 60l-60 60"/>',energy:'<path d="M45 118C76 35 112 153 175 54"/><circle cx="45" cy="118" r="9"/><circle cx="175" cy="54" r="9"/>',nutrition:'<circle cx="110" cy="90" r="60"/><path d="M110 30v60l52 30M110 90l-40 45"/>',strength:'<path d="M35 90h150M55 55v70M75 42v96M145 42v96M165 55v70"/>',cardio:'<path d="M25 95h35l18-45 35 90 26-55h56"/>',recovery:'<circle cx="110" cy="90" r="60"/><path d="M155 120A55 55 0 0 1 80 43a45 45 0 0 0 75 77Z"/>',mind:'<circle cx="110" cy="90" r="60"/><path d="M110 45v45l32 20M110 18v14M110 148v14M38 90H24m172 0h-14"/>',money:'<path d="M32 145h160M55 130V80m35 50V55m35 75V70m35 60V38"/><path d="m45 65 45-22 35 12 45-34"/>',utility:'<path d="M35 60h150m-35-25 35 25-35 25M185 120H35m35-25-35 25 35 25"/>'};return `<svg viewBox="0 0 220 180">${shapes[id]}</svg>`}
function sampleChart(lang){return `<div class="sample-chart panel"><header><span>${bi('Талия','Waist',lang)}</span><strong>−3.2 <small>cm</small></strong></header><svg viewBox="0 0 440 190" role="img" aria-label="${bi('Пример динамики талии: снижение на 3,2 сантиметра','Example waist trend: decrease of 3.2 centimeters',lang)}"><path class="axis" d="M30 25v135h380"/><polyline points="30,45 125,68 220,74 315,118 410,135"/><g><circle cx="30" cy="45" r="5"/><circle cx="125" cy="68" r="5"/><circle cx="220" cy="74" r="5"/><circle cx="315" cy="118" r="5"/><circle cx="410" cy="135" r="5"/></g></svg><div><span>${bi('Начало','Start',lang)} <b>94.0 cm</b></span><span>${bi('Сейчас','Current',lang)} <b>90.8 cm</b></span></div></div>`}
